INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(28701, '2 Timothy 2:7', '2 Timothy', 2, 7, '&nbsp;څۀ چې زۀ وايم په هغې باندې سوچ وکړه نو بيا به مالِک تا له د ټولو خبرو پوهه درکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28702, '2 Timothy 2:8', '2 Timothy', 2, 8, '&nbsp;ياد ساته چې عيسىٰ مسيح د مړو نه راژوندے شوے دے او د داؤد د نسل نه دے، دا زما زيرے دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28703, '2 Timothy 2:9', '2 Timothy', 2, 9, '&nbsp;د کوم دپاره چې ما سختۍ وزغملې تر دې چې د مجرم په شان په زنځير وتړلے شوم، خو د خُدائ پاک کلام په زنځير تړلے کېدے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28704, '2 Timothy 2:10', '2 Timothy', 2, 10, '&nbsp;په دې وجه زۀ د غوره شوو د خاطره دا هر څۀ په خپل ځان برداشت کوم نو د دې دپاره چې هغوئ هم هغه خلاصون او ابدى جلال چې د عيسىٰ مسيح په وسيله دے حاصل کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28705, '2 Timothy 2:11', '2 Timothy', 2, 11, '&nbsp;دا خبرې رښتيا دى چې، ”کۀ مونږ د هغۀ سره مړۀ شُو نو مونږ به د هغۀ سره ژوندى هم شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28706, '2 Timothy 2:12', '2 Timothy', 2, 12, '&nbsp;کۀ مونږ سختۍ وزغمو نو د هغۀ سره به بادشاهى هم کوُو، کۀ مونږ د هغۀ نه منکر شُو نو هغه به هم زمونږ نه منکر شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28707, '2 Timothy 2:13', '2 Timothy', 2, 13, '&nbsp;کۀ مونږ بې‌وفا شُو خو هغه به وفادار پاتې شى، ځکه چې هغه نۀ شى کولے چې د خپل ځان نه اِنکار وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28708, '2 Timothy 2:14', '2 Timothy', 2, 14, '&nbsp;دا خبرې هغوئ ته وريادې کړه او د خُدائ پاک په وړاندې ورته خبردارے ورکړه چې لفظى تکرار دې ونۀ کړى، ځکه چې د دې نه هيڅ نۀ جوړيږى بلکې صرف اورېدونکى بربادوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28709, '2 Timothy 2:15', '2 Timothy', 2, 15, '&nbsp;خپل ځان د خُدائ پاک په وړاندې مقبول او د يو داسې خدمتګار په شان د پېش کولو کوشش وکړه چې په خپل کار نۀ شرميږى، او چې د حق د کلام تعليم په صحيح توګه پېش کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28710, '2 Timothy 2:16', '2 Timothy', 2, 16, '&nbsp;د فضولو خبرو نه خپل ځان ساته ځکه چې دا خلق لا نور د بې‌دينۍ طرف ته بوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28711, '2 Timothy 2:17', '2 Timothy', 2, 17, '&nbsp;د هغوئ خبرې لکه د ناسور په شان خوريږى، او هميناوس او فيلتوس په هغوئ کښې دى', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28712, '2 Timothy 2:18', '2 Timothy', 2, 18, '&nbsp;څوک چې د حقيقت نه بې‌لارې شوى دى او داسې دعوىٰ کوى چې د بيا راژوندى کېدلو وخت خو وشو. او هغوئ د څۀ خلقو ايمان خرابوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28713, '2 Timothy 2:19', '2 Timothy', 2, 19, '&nbsp;خو بيا هم د خُدائ پاک بنياد مضبوط دے او په هغې دا ليکلى دى چې، ”مالِک خپل هغه خلق پېژنى،“ او، ”څوک چې د هغۀ دى د مالِک نوم اخلى، هغه دې د شرارت نه واوړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28714, '2 Timothy 2:20', '2 Timothy', 2, 20, '&nbsp;په لوئ کور کښې نۀ يواځې د سرو زرو او سپينو زرو لوښى وى بلکې د لرګى او خاورين لوښى هم وى، دا څۀ د خاص او څۀ د عام استعمال دپاره وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28715, '2 Timothy 2:21', '2 Timothy', 2, 21, '&nbsp;څوک چې خپل ځانونه د هغه څيزونو نه پاک کړى چې شرمناک وى نو هغه به د خاص استعمال او د عزت لوښى شى او د کور د مالِک د هر ښۀ کار دپاره به تيار او فائده مند وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28716, '2 Timothy 2:22', '2 Timothy', 2, 22, '&nbsp;نو د ځوانۍ د خواهشاتو نه تېښته کوه، او د هغې په ځائ د صداقت، ايمان او مينې او د صُلحې طلبګار اوسه، او بيا د هغه کسانو سره شامل شه څوک چې د مالِک نه په پاک زړۀ سره دُعا غواړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28717, '2 Timothy 2:23', '2 Timothy', 2, 23, '&nbsp;خو د بې‌وقوفۍ او د جهالت د بحثونو نه ځان په ډډه ساته، ځکه تا ته پته ده چې د دې نه صرف جګړې جوړيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28718, '2 Timothy 2:24', '2 Timothy', 2, 24, '&nbsp;او دا په کار نۀ دى چې د مالِک خادِم دې جګړمار وى، بلکې هغه دې د ټولو سره نرمى کوى او هغه دې قابل اُستاذ او صبرناک وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28719, '2 Timothy 2:25', '2 Timothy', 2, 25, '&nbsp;او هغوئ دې مخالفت کوونکى په نرمۍ سره سم کړى ځکه چې کېدے شى چې خُدائ پاک هغوئ ته د توبې کولو توفيق ورکړى نو چې هغوئ حق وپېژنى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28720, '2 Timothy 2:26', '2 Timothy', 2, 26, '&nbsp;نو بيا به هغوئ د اِبليس د دام نه آزاد شى چا چې دوئ د خپلې مرضۍ د پوره کولو دپاره په هغې کښې نيولى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28721, '2 Timothy 3:1', '2 Timothy', 3, 1, '&nbsp;خو تاسو په دې پوهه شئ چې په آخرى ورځو کښې به سخت وختونه راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28722, '2 Timothy 3:2', '2 Timothy', 3, 2, '&nbsp;ځکه چې خلق به خود غرضه، لالچيان، لافې کوونکى، مغروره، ګستاخه، د مور پلار نافرمانه، ناشُکره، بې‌دينه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28723, '2 Timothy 3:3', '2 Timothy', 3, 3, '&nbsp;بې‌رحمه، سخت زړۀ لرونکى، غېبت کوونکى، نۀ زغمونکى، بد خويه، د نېکۍ دشمن،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28724, '2 Timothy 3:4', '2 Timothy', 3, 4, '&nbsp;دوکه باز، بې‌پرواه، کبرژن، او د خُدائ پاک په نسبت عېش زيات خوښوونکى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28725, '2 Timothy 3:5', '2 Timothy', 3, 5, '&nbsp;هغوئ به په ظاهره د ديندارۍ نمائش کوى خو په زړۀ کښې به يې يقين نۀ وى. د داسې خلقو نه ځان ساته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28726, '2 Timothy 3:6', '2 Timothy', 3, 6, '&nbsp;په دوئ کښې هغه خلق دى څوک چې کورونو ته په څۀ چل ورننوځى او هغه کم عقلې ښځې په خپل قابو کښې راولى کومې چې په خپلو ګناهونو کښې راګېرې وى او چې د رنګارنګ خواهشونو لاندې راګېرې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28727, '2 Timothy 3:7', '2 Timothy', 3, 7, '&nbsp;داسې ښځې همېشه د زده کولو کوشش کوى خو حق پېژندلو ته نۀ رسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28728, '2 Timothy 3:8', '2 Timothy', 3, 8, '&nbsp;او څنګه چې ينيس او يمبريس د موسىٰ مخالفت کړے وو، نو دې بې‌عقلو او دروغژنو ايمان لرونکو سړو هم د حقيقت مخالفت وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28729, '2 Timothy 3:9', '2 Timothy', 3, 9, '&nbsp;خو هغوئ به ډېره ترقى ونۀ کړى ځکه چې د هغه دوو سړو په شان به د دوئ کم عقلتوب هم هر چا ته څرګند شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28730, '2 Timothy 3:10', '2 Timothy', 3, 10, '&nbsp;خو تۀ زما د تعليم، زما د چال چلن، زما د ژوند د مقصد، زما د ايمان، زما د زغم، زما د مينې او په ايمان کښې زما د مضبوطوالى نه خبر يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28731, '2 Timothy 3:11', '2 Timothy', 3, 11, '&nbsp;تا ته پته ده د هغه سختۍ او تکليفونو يعنې هغه تکليفونه کوم چې په اَنطاکيه، اِکونيوم او په لستره کښې په ما راغلل خو مالِک زۀ د هغې ټولو نه بچ کړم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28732, '2 Timothy 3:12', '2 Timothy', 3, 12, '&nbsp;په حقيقت کښې هر هغه څوک چې د عيسىٰ مسيح په يووالى کښې په ديندارۍ ژوند تېرول غواړى، نو هغوئ به زورول کيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28733, '2 Timothy 3:13', '2 Timothy', 3, 13, '&nbsp;خو خراب او دوکه باز خلق به نورو له په دوکه ورکولو او دوکه خوړلو کښې لا زياتيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28734, '2 Timothy 3:14', '2 Timothy', 3, 14, '&nbsp;خو تۀ په هغه خبرو عمل کوه کومې چې تا ته درښودلے شوې دى او ستا يقين دے چې هغه رښتيا دى، او تۀ په دې پوهه يې چې چا تا ته درښودلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28735, '2 Timothy 3:15', '2 Timothy', 3, 15, '&nbsp;او تۀ د وړوکوالى نه د هغه پاکو صحيفو نه خبر يې، کومې چې تا ته په عيسىٰ مسيح د ايمان راوړلو په وسيله د خلاصون پوهه درکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28736, '2 Timothy 3:16', '2 Timothy', 3, 16, '&nbsp;هره يوه صحيفه د خُدائ پاک د خوا نه الهام شوې ده او دا د تعليم ورکولو، ملامتولو، د اصلاح او د صادقه تربيت دپاره فائده مندې هم دى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28737, '2 Timothy 3:17', '2 Timothy', 3, 17, '&nbsp;د دې دپاره چې د خُدائ پاک خِدمتګاران د دې قابل شى او د هر نېک کار کولو دپاره تيار شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28738, '2 Timothy 4:1', '2 Timothy', 4, 1, '&nbsp;د خُدائ پاک او د عيسىٰ مسيح په حضور کښې څوک چې به د ژوندو او د مړو عدالت کوى، او د هغۀ د ظاهرېدو او د بادشاهۍ په ياد کښې زۀ په تا زور راوړم چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28739, '2 Timothy 4:2', '2 Timothy', 4, 2, '&nbsp;تۀ د کلام زيرے ورکوه او وخت ناوخته دې کار ته تيار اوسه، او په تعليم ورکولو کښې په صبر سره د هغوئ اصلاح کوه او ملامتوه يې او ورته ډاډګيرنه هم ورکوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28740, '2 Timothy 4:3', '2 Timothy', 4, 3, '&nbsp;ځکه چې داسې وخت راروان دے چې خلق به صحيح تعليم نۀ زغمى، بلکې د خپلې خوښې په مطابق به داسې اُستاذان راټول کړى چې هغوئ ته به هغه څۀ وښائى چې کوم اورېدل غواړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28741, '2 Timothy 4:4', '2 Timothy', 4, 4, '&nbsp;خو هغوئ به حق ته غوږ نۀ کېږدى او فرضى قيصو پسې به ګرځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28742, '2 Timothy 4:5', '2 Timothy', 4, 5, '&nbsp;خو تۀ په هر حالت کښې خپل ځان په هوش کښې ساته، سختۍ وزغمه، د زيرى کار کوه او د خُدائ پاک د خادِم په حيث خپل خِدمت پوره کوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28743, '2 Timothy 4:6', '2 Timothy', 4, 6, '&nbsp;ترڅو چې زما خبره ده زۀ خو د مخکښې نه لکه د ميو نذرانې په شان په قربان‌ګاه شيندلے شوے يم او زما د رخصتېدو وخت راغلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28744, '2 Timothy 4:7', '2 Timothy', 4, 7, '&nbsp;ما ښۀ جنګ وکړو، خپله منډه مې پوره کړه، او تر آخره په خپل ايمان قائم پاتې شوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28745, '2 Timothy 4:8', '2 Timothy', 4, 8, '&nbsp;نو د اوس نه د صداقت تاج زما دپاره تيار دے، کوم چې به د صداقت قاضى مالِک ما ته په هغه ورځ راکړى، او دا صرف زما دپاره نه بلکې د هغوئ ټولو دپاره هم دے څوک چې د هغۀ د راتلو خواهشمند دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28746, '2 Timothy 4:9', '2 Timothy', 4, 9, '&nbsp;خو کوشش وکړه چې ما له زر تر زره راشئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28747, '2 Timothy 4:10', '2 Timothy', 4, 10, '&nbsp;ځکه چې ديماس د دې موجوده دُنيا په مينه کښې زۀ پرېښودلم او تِسالونيکې ته لاړو او کريسکينس ګلتيه ته لاړو او تيطوس دلماتيه ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28748, '2 Timothy 4:11', '2 Timothy', 4, 11, '&nbsp;صرف لوقا ما سره دے خو مرقوس راپېدا کړه او ځان سره يې راوله ځکه چې هغه زما سره په خِدمت کښې فائده مند دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28749, '2 Timothy 4:12', '2 Timothy', 4, 12, '&nbsp;ما تخيکوس اِفِسوس ته لېږلے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28750, '2 Timothy 4:13', '2 Timothy', 4, 13, '&nbsp;کله چې تۀ راځې هغه چُوغه چې ما د ترواس په ښار کښې د کرپس په کور کښې پرېښې ده او زما کتابونه او خاص کر زما هغه د څرمنې نسخې هم ځان سره راوړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28751, '2 Timothy 4:14', '2 Timothy', 4, 14, '&nbsp;سکندر مسګر ما ته لوئ نقصان راکړے دے. خو مالِک خُدائ به هغۀ ته د خپل عمل په مطابق بدله ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28752, '2 Timothy 4:15', '2 Timothy', 4, 15, '&nbsp;او تۀ هم د هغۀ نه ځان ساته، ځکه چې هغۀ زمونږ د پېغام ډېر په سختۍ سره مخالفت کړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(28753, '2 Timothy 4:16', '2 Timothy', 4, 16, '&nbsp;په عدالت کښې زما د اولنۍ پېشۍ په وخت څوک هم ما سره ونۀ درېدل بلکې ټولو زۀ ځانله پرېښودم. خُدائ دې هغوئ په دې ګناه ونۀ نيسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
