(28766, 'Titus 1:7', 'Titus', 1, 7, '&nbsp;ځکه چې د جماعت مشر دې د خُدائ پاک د کار د مُختار کېدو په وجه بې‌اِلزامه وى، هغه دې نۀ سرکشه، نۀ غصه ناک، نۀ شرابى، نۀ جګړه مار، او نۀ دې د ناجائزې ګټې حرصناک وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
